<template><div class="ui-changes"><header><div><strong>{{title}}</strong><span>{{changes.length}} 项变更</span></div><UiButton v-if="collapsible" density="mini" variant="quiet" @click="expanded=!expanded">{{expanded?'收起':'展开'}}</UiButton></header><div v-if="expanded" class="ui-changes__list"><div v-for="change in changes" :key="change.field" class="ui-changes__row"><strong>{{change.label||change.field}}</strong><span class="before">{{display(change.before)}}</span><Icon name="arrowRight" size="xs"/><span class="after">{{display(change.after)}}</span></div></div></div></template>
<script setup lang="ts">import{ref}from'vue';import Icon from '@/components/icons/Icon.vue';import UiButton from './UiButton.vue';export interface UiFieldChange{field:string;label?:string;before:unknown;after:unknown;sensitive?:boolean}const props=withDefaults(defineProps<{changes:UiFieldChange[];title?:string;collapsible?:boolean;defaultExpanded?:boolean}>(),{title:'修改摘要',collapsible:true,defaultExpanded:true});const expanded=ref(props.defaultExpanded);function display(value:unknown){if(value===null||value===undefined||value==='')return'未设置';if(typeof value==='object')return JSON.stringify(value);return String(value)}</script>
<style scoped>.ui-changes{border:1px solid var(--ui-border-soft);border-radius:var(--ui-radius);background:var(--ui-surface)}.ui-changes>header{display:flex;align-items:center;justify-content:space-between;padding:8px 10px;background:var(--ui-surface-muted)}.ui-changes>header>div{display:flex;align-items:center;gap:7px}.ui-changes header strong{font-size:12px}.ui-changes header span{color:var(--ui-text-soft);font-size:10px}.ui-changes__list{display:grid}.ui-changes__row{display:grid;grid-template-columns:minmax(90px,.8fr) minmax(0,1fr) auto minmax(0,1fr);align-items:center;gap:8px;min-height:36px;padding:5px 10px;border-top:1px solid var(--ui-border-soft);font-size:12px}.ui-changes__row strong{font-weight:500}.ui-changes__row span{min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.ui-changes__row .before{color:var(--ui-text-soft);text-decoration:line-through}.ui-changes__row .after{color:var(--ui-text)}@media(max-width:560px){.ui-changes__row{grid-template-columns:90px 1fr auto}.ui-changes__row .after{grid-column:2}.ui-changes__row svg{grid-column:3;grid-row:1/3}.ui-changes__row .before{grid-column:2}}</style>
